#include "fractal/compatibility.h"
#include <string.h>
static bool overlap(fractal_version_range a,fractal_version_range b,uint32_t*out){uint32_t lo=a.minimum>b.minimum?a.minimum:b.minimum;uint32_t hi=a.maximum<b.maximum?a.maximum:b.maximum;if(lo>hi)return false;*out=hi;return true;}
static bool has_feature(const fractal_feature*f,uint32_t n,fractal_feature x){uint32_t i;for(i=0;i<n;i++)if(f[i].id==x.id&&f[i].version==x.version)return true;return false;}
fractal_compatibility_selection fractal_compatibility_negotiate(const fractal_compatibility_client_hello*c,const fractal_compatibility_service_hello*s){fractal_compatibility_selection r;uint32_t i;memset(&r,0,sizeof(r));if(!c||!s){r.result=FRACTAL_CAPABILITY_MISMATCH;return r;}if(s->client_upgrade_required||c->contract_version<s->minimum_supported_client_contract){r.result=FRACTAL_CLIENT_UPGRADE_REQUIRED;return r;}if(s->service_upgrade_required){r.result=FRACTAL_SERVICE_UPGRADE_REQUIRED;return r;}if(!overlap(c->protocol_family,s->protocol_family,&r.selected_protocol_family)){r.result=FRACTAL_NO_COMMON_PROTOCOL;return r;}if(!overlap(c->message_schema,s->message_schema,&r.selected_schema_version)){r.result=FRACTAL_NO_COMMON_SCHEMA;return r;}if(!overlap(c->workspace_contract,s->workspace_contract,&r.selected_workspace_contract)){r.result=FRACTAL_NO_COMMON_WORKSPACE_CONTRACT;return r;}if(!overlap(c->pairing_contract,s->pairing_contract,&r.selected_pairing_contract)){r.result=FRACTAL_NO_COMMON_PAIRING_CONTRACT;return r;}for(i=0;i<c->feature_count&&i<FRACTAL_FEATURE_CAPACITY;i++){if(has_feature(s->features,s->feature_count,c->features[i])){r.features[r.feature_count++]=c->features[i];}else if(c->features[i].required){r.result=FRACTAL_CAPABILITY_MISMATCH;return r;}}r.service_compatibility_epoch=s->service_compatibility_epoch;r.service_restart_epoch=s->service_restart_epoch;r.result=s->deprecated_feature_count?FRACTAL_COMPATIBLE_WITH_DEPRECATIONS:FRACTAL_COMPATIBLE;return r;}
